const pr = $('normalizeClient').item.json;
const p = pr.fields ? pr.fields : pr;

const bioItems = $('getBiometrics').all().map(it => (it.json && it.json.fields) ? it.json.fields : (it.json || {}));
let latest = null;
for (const b of bioItems) { if (b && b.recovery_score != null && b.recovery_score !== '') { if (!latest || String(b.date||'') > String(latest.date||'')) latest = b; } }
const recovery = latest ? Number(latest.recovery_score) : 60;

const nudgeItems = $('getRecentNudges').all().map(it => (it.json && it.json.fields) ? it.json.fields : (it.json || {}));
let lastTs = null; const contents = [];
for (const nz of nudgeItems) { if (nz && nz.timestamp) { const t = new Date(nz.timestamp).getTime(); if (!isNaN(t) && (!lastTs || t > lastTs)) lastTs = t; } if (nz && nz.nudge_content) contents.push(nz.nudge_content); }
const last3 = contents.slice(0, 3);

const contactId = (p.ghl_contact_id || '');
const client_id = (p.client_id || '');
const baseOut = { send: false, skip: true, contactId: contactId, client_id: client_id, trigger_reason: 'focus_block', recovery_used: recovery, body: null, recent_nudges: last3 };

if (lastTs && (Date.now() - lastTs) / 60000 < 110) return [{ json: Object.assign({}, baseOut, { skip_reason: 'throttled' }) }];
if (!contactId) return [{ json: Object.assign({}, baseOut, { skip_reason: 'no_contact' }) }];


let openTasks = [];
try {
  const tj = $('getGhlTasks').item.json || {};
  const tl = Array.isArray(tj.tasks) ? tj.tasks : [];
  const nowLoc = new Date(new Date().toLocaleString('en-US', { timeZone: __tz }));
  const todayStr = nowLoc.getFullYear() + '-' + String(nowLoc.getMonth() + 1).padStart(2, '0') + '-' + String(nowLoc.getDate()).padStart(2, '0');
  const open = tl.filter(t => t && !t.completed && t.title);
  const dueToday = open.filter(t => String(t.dueDate || '').slice(0, 10) <= todayStr);
  const rest = open.filter(t => !dueToday.includes(t));
  openTasks = dueToday.concat(rest).slice(0, 5).map(t => String(t.title).slice(0, 60) + (String(t.dueDate || '').slice(0, 10) === todayStr ? ' (due today)' : ''));
} catch (e) { openTasks = []; }
const priorities = [p.top_priority_1, p.top_priority_2, p.top_priority_3].filter(Boolean);
const focus = priorities[0] || 'your top priority';

const system = [
  'You are a sharp executive coach sending ONE SMS focus nudge.',
  'CLIENT: ' + (p.full_name || 'Client') + ', ' + (p.business_stage || 'growing') + ' stage, recovery ' + recovery + '/100.',
  'CURRENT FOCUS: ' + focus + '.',
  openTasks.length ? ('OPEN TASKS: ' + openTasks.join('; ') + '. Reference the most urgent one directly.') : '',
  last3.length ? ('AVOID repeating these recent nudges: ' + last3.join(' | ')) : '',
  'OUTPUT RULES: ONE plain-text SMS under 100 characters. No emojis or special symbols. Punchy, specific, action-oriented. No greeting, no signature.'
].filter(Boolean).join('\n');

const body = { model: 'claude-sonnet-4-6', max_tokens: 80, system: system, messages: [{ role: 'user', content: 'Write my focus nudge now.' }] };
return [{ json: { send: true, recent_nudges: last3, skip: false, body: body, contactId: contactId, trigger_reason: 'focus_block', client_id: client_id, recovery_used: recovery } }];

let text = $input.first().json.content[0].text;
const bn = $('buildNudgePrompt').item.json;
text = text.replace(/[—–]/g, '-').replace(/[‘’]/g, "'").replace(/[“”]/g, '"').replace(/[^�-]/g, '').replace(/\s+/g, ' ').trim();
let nudge = text.slice(0, 130);

// Hard dedup: if the new nudge is too similar to a recent one, skip the send (avoid near-duplicates).
function norm(s){return String(s||'').toLowerCase().replace(/[^a-z0-9 ]/g,'').replace(/\s+/g,' ').trim();}
function jaccard(a,b){var A=new Set(norm(a).split(' ').filter(Boolean));var B=new Set(norm(b).split(' ').filter(Boolean));if(!A.size||!B.size)return 0;var inter=0;A.forEach(function(x){if(B.has(x))inter++;});return inter/(A.size+B.size-inter);}
const recent = Array.isArray(bn.recent_nudges)?bn.recent_nudges:[];
let dup=false;
for(const r of recent){ if(jaccard(nudge,r) >= 0.6){ dup=true; break; } }
if(dup){ return [{ json: { send:false, skip:true, skip_reason:'duplicate', contactId: bn.contactId, client_id: bn.client_id } }]; }

return [{ json: { send: true, nudge_content: nudge, contactId: bn.contactId, trigger_reason: bn.trigger_reason, client_id: bn.client_id, reply: nudge } }];

